  'dom.daysLeft': 'Kalan gün', 'dom.expiry': 'Bitiş', 'dom.registrar': 'Registrar', 'dom.source': 'Kaynak', 'dom.sourceVia': 'Cevabı veren whois kaynağı', 'dom.nsResolves': 'NS çözülüyor', 'dom.lastCheck': 'Son kontrol',
